import React from "react";

const QuestionCard = ({
    question,
    options,
    currentQuestion,
    totalQuestions,
    handleNext,
    handlePrevious,
    handleSubmit,
    isLastQuestion,
    quizSubmitted,
    isFirstQuestion,
    selectedAnswers,
    setSelectedAnswers,
}) => {
    // Safeguard against invalid options
    const optionList = options && Array.isArray(options) ? options : [];

    // Retrieve the selected option for the current question
    const selectedOption = selectedAnswers[currentQuestion];

    // Handle option selection for the current question
    const handleOptionClick = (index) => {
        if (!quizSubmitted) {
            setSelectedAnswers((prevAnswers) => {
                const updatedAnswers = [...prevAnswers];
                updatedAnswers[currentQuestion] = index; // Update the selected option for this question
                return updatedAnswers;
            });
        }
    };

    return (
        <div className="max-w-md mx-auto p-4 border rounded shadow-md bg-white">
            {/* Question Info */}
            <p className="text-lg font-semibold">
                Question {currentQuestion + 1} of {totalQuestions}
            </p>
            <h2 className="text-xl font-bold my-4">{question}</h2>

            {/* Options List */}
            <div className="mb-4">
                {optionList.length > 0 ? (
                    optionList.map((option, index) => (
                        <button
                            key={index}
                            className={`block w-full px-4 py-2 mb-2 text-left border rounded ${
                                selectedOption === index ? "bg-blue-500 text-white" : "bg-gray-100"
                            }`}
                            onClick={() => handleOptionClick(index)} // Set selected option
                            disabled={quizSubmitted} // Disable changes if quiz is submitted
                        >
                            {option}
                        </button>
                    ))
                ) : (
                    <p>No options available for this question.</p>
                )}
            </div>

            {/* Navigation Buttons */}
            <div className="flex justify-between">
                <button
                    className="px-4 py-2 bg-gray-500 text-white rounded disabled:bg-gray-300"
                    onClick={handlePrevious}
                    disabled={isFirstQuestion || quizSubmitted}
                >
                    Previous
                </button>
                {isLastQuestion ? (
                    <button
                        className="px-4 py-2 bg-green-500 text-white rounded"
                        onClick={handleSubmit}
                        disabled={quizSubmitted}
                    >
                        Submit
                    </button>
                ) : (
                    <button
                        className="px-4 py-2 bg-blue-500 text-white rounded"
                        onClick={handleNext}
                        disabled={quizSubmitted}
                    >
                        Next
                    </button>
                )}
            </div>
        </div>
    );
};

export default QuestionCard;
